{
  "chapter_proposals": [
    {
      "chapter_id": "CH3",
      "title": "实证表现：已制备器件的性能边界与评估基准",
      "purpose": "批判性评估当前可见光消色差超构透镜的实验数据，揭示现有性能报告中的系统性偏差（如效率定义模糊、不恰当的成像质量对比），并量化实验水平与理论物理极限（带宽饱和区）之间的差距。本章旨在建立一套更严谨的评估范式，区分受限于材料/工艺的损失与受限于单界面几何/色散原理的根本瓶颈。",
      "scope": "聚焦于高数值孔径（NA > 0.5）可见光波段超构透镜的实测数据。重点分析效率指标的定义差异（绝对 vs. 相对，平均 vs. 局部）、成像质量表征方法的局限性（FWHM vs. MTF），以及单片器件与复消色差物镜对比的物理无效性。范围涵盖对 Kho16 (TiO2) 和 Lal99 (TiO2 blazed-binary) 等关键案例的重分析，但不涉及多元件复合系统的详细设计优化。",
      "excluded_source_handles": [],
      "substantive_threads": [
        {
          "theme": "效率数据的解构与局部衰减分析",
          "argument": "现有文献报道的全孔径平均效率往往掩盖了高 NA 区域（边缘视场）的严重性能衰退。必须区分‘绝对效率’（包含菲涅尔反射损失）与‘相对效率’（仅衍射效率），并指出共振型设计在斜入射下因反对称模式激发导致的效率凹陷是造成边缘区域性能恶化的微观机制，而非单纯的制造误差。",
          "evidence_base": ["P0001"],
          "case_study": "重析 Kho16 报道的 TiO2 超构透镜数据：其声称的 86% (蓝光) 至 66% (红光) 效率若为扣除反射后的相对值，则实际系统透过率更低；更重要的是，该平均值未反映边缘环带因大角度入射激发的寄生模式损耗。对比 Lal99 的波导型设计，后者因偏振不敏感且无共振模式耦合问题，在斜入射下表现出更稳定的效率曲线，证明结构设计对局部效率分布的决定性作用。",
          "synthesis_point": "效率不仅是材料吸收或散射的结果，更是相位梯度设计与入射角耦合的函数。在高 NA 下，‘平均效率’是一个误导性指标，必须报告随径向位置变化的效率分布以真实反映器件可用性。"
        },
        {
          "theme": "成像质量评估的误区与‘不恰当比较’批判",
          "argument": "将单片超构透镜与多片式商业复消色差物镜直接进行宽视场成像对比在物理上是无效的。单界面器件无法利用轴向距离校正彗差、场曲和像散，其低像差视场在高 NA 下被限制在微米量级（<5 µm）。依赖焦点半高宽（FWHM）作为唯一评价指标忽略了旁瓣能量和调制传递函数（MTF）在空间频率上的衰减，导致对成像质量的过度乐观估计。",
          "evidence_base": ["P0001"],
          "case_study": "剖析 Kho16 与商用物镜的对比实验：虽然中心视场 FWHM 接近衍射极限，但在离轴几微米处，单片超构透镜的 MTF 迅速崩塌，而商用物镜凭借多片结构维持了良好的对比度。指出这种比较忽视了单界面几何像差的根本限制，属于‘苹果与橘子’的比较。",
          "synthesis_point": "真正的性能基准应基于 MTF 曲线而非单一 FWHM 值，且必须在明确的视场角范围内进行比较。对于单片超构透镜，其应用场景应重新定位为对视场要求极低但对厚度敏感的点对点互连或特定滤波应用，而非通用成像。"
        },
        {
          "theme": "实验现状与理论饱和区的差距定位",
          "argument": "当前实验器件尚未触及由群延迟需求非单调性决定的‘带宽饱和’理论极限。多数器件的性能瓶颈仍主要源于材料损耗（如 TiO2 在蓝紫光段的吸收）、纳米柱侧壁粗糙度引起的散射以及未能完全补偿高阶色散项，而非达到了 P0002 所述的物理天花板。",
          "evidence_base": ["P0001", "P0002"],
          "case_study": "结合 P0002 的理论模型，指出当前 NA=0.8 器件的实际工作带宽远小于理论允许的最大带宽（即使在考虑带宽饱和效应后）。这表明通过改进材料纯度、优化纳米柱几何参数以减少散射损耗，仍有显著的性能提升空间，无需立即转向复杂的多层或非局部架构来解决带宽问题。",
          "synthesis_point": "区分‘工艺限制’与‘物理极限’至关重要。目前的实证数据表明，领域仍处于克服工艺缺陷的阶段，过早宣称触及物理极限可能误导研究方向，忽视了对基础材料和制造工艺的进一步挖掘。"
        }
      ],
      "supplement_requests": [
        {
          "need_id": "Q02_MTF_ReEval",
          "description": "请求获取或计算 Kho16 器件在边缘视场（如 FOV > 2°）下的调制传递函数（MTF）数据，或与理想衍射极限 MTF 的偏差曲线，以定量支撑‘不恰当比较’的论点。若原始数据不可得，需基于 P0001 提供的物理模型构建定性对比图示。",
          "priority": "high"
        },
        {
          "need_id": "Q01_Angle_Efficiency_Data",
          "description": "请求补充共振型超构透镜在不同入射角下的效率衰减定量数据（特别是 TE/TM 偏振分离情况），以验证反对称模式激发机制对全孔径平均效率的具体影响权重。",
          "priority": "medium"
        }
      ],
      "directed_reads": [
        {
          "source_handle": "P0001",
          "focus_area": "关于 Kho16 效率数据统计方法的批判性评论部分，以及 Lal99 波导型器件的角度稳定性数据。重点提取文中对‘绝对效率’与‘相对效率’定义的辨析，以及对单界面几何像差限制视场的具体数值估算（如 NA=0.5 时的视场半径）。"
        },
        {
          "source_handle": "P0002",
          "focus_area": "理论带宽饱和曲线的数值结果部分，用于确定在当前典型 NA 值下，理论允许的最大带宽是多少，以便与实验值进行差距对比。注意记录其模型假设（标量近似）对结论适用性的限制。"
        }
      ],
      "transition_logic": "本章通过揭示实验数据中的评估偏差和工艺局限，明确了当前技术与理论极限的真实距离。这不仅修正了对现有器件性能的过度解读，也为未来研究指明了方向：在追求新奇的色散补偿机制之前，必须首先解决材料损耗、制造公差及单界面几何像差这些基础性问题。接下来的总结章节将综合物理界限、设计权衡与实证差距，提出一个分层级的技术发展路线图。"
    }
  ],
  "screened_sources": []
}

